WfbAodMask.mc:
import Toybox.Graphics;
import Toybox.Lang;

//! A moving 2x2 pixel mask over the AOD frame (`aod: {mask: ...}`,
//! docs/guide/always-on-display.md).
module WfbAodMask {

    //! Force every pixel except one per on-screen 2x2 tile to black, moving
    //! which pixel of each tile stays lit once a minute.
    //!
    //! `phase = minute mod 4` selects `(dx, dy)` from the fixed 4-cycle
    //! `[(0,0), (1,0), (1,1), (0,1)]` -- each step moves to a 4-neighbour,
    //! never a diagonal jump, and 60/1440 are both multiples of 4 so the
    //! cycle stays continuous across the hour and the day. The pixel kept
    //! lit at device coordinate `(x, y)` is exactly the one with
    //! `x mod 2 == dx` and `y mod 2 == dy`; every other pixel is blacked
    //! out. The black set is `{y mod 2 != dy} union {x mod 2 != dx}` --
    //! every other row plus every other column -- so this is two loops of
    //! 1px `fillRectangle` strips, never a bitmap: no alpha, no
    //! `BufferedBitmap`, no graphics-pool memory, and it runs on every
    //! device (`Dc.fillRectangle`/`setColor`/`getWidth`/`getHeight` and
    //! `System.getClockTime` are universal). Anti-aliasing is turned off
    //! first so the 1px strips land on exact pixels, the same guard
    //! `applyAntiAlias` uses.
    //!
    //! Called once per AOD frame, after every element the frame draws, with
    //! `minute` from `System.getClockTime().min` (0-59).
    function apply(dc as Dc, minute as Number) as Void {
        var phase = minute % 4;
        var dx = (phase == 1 || phase == 2) ? 1 : 0;
        var dy = (phase >= 2) ? 1 : 0;
        if (dc has :setAntiAlias) {
            dc.setAntiAlias(false);
        }
        dc.setColor(Graphics.COLOR_BLACK, Graphics.COLOR_BLACK);
        var w = dc.getWidth();
        var h = dc.getHeight();
        for (var y = 1 - dy; y < h; y += 2) {
            dc.fillRectangle(0, y, w, 1);
        }
        for (var x = 1 - dx; x < w; x += 2) {
            dc.fillRectangle(x, 0, 1, h);
        }
    }
}

WfbArc.mc:
import Toybox.Graphics;
import Toybox.Lang;

//! Progress arcs.
//!
//! Garmin has no filled-sector primitive -- there is no `fillArc`, `fillSector`
//! or `drawSector` anywhere in the API.  A ring is `setPenWidth` plus `drawArc`
//! and nothing else, which is why thickness is a pen width, cap style is not
//! selectable, and true annuli and gradient sweeps are not offered.
module WfbArc {

    //! Draw `fraction` (0..1) of an arc.
    //!
    //! @param startDegrees Garmin convention: 3 o'clock is 0, counter-clockwise
    //!        positive.  The generator has already converted from the author's
    //!        clockwise-from-12 angles.
    //! @param sweepDegrees Signed sweep in the author's clockwise sense.
    function drawProgress(
        dc as Graphics.Dc,
        cx as Number, cy as Number, radius as Number, penWidth as Number,
        startDegrees as Float, sweepDegrees as Float, fraction as Float
    ) as Void {
        if (fraction <= 0.0 || radius <= 0) { return; }
        // A fill under half a degree draws nothing; see drawSpan.
        var swept = sweepDegrees * ((fraction > 1.0) ? 1.0 : fraction);
        drawSpan(dc, cx, cy, radius, penWidth, startDegrees, swept);
    }

    //! Draw a fixed span, used for a gauge's unfilled track.
    function drawSpan(
        dc as Graphics.Dc,
        cx as Number, cy as Number, radius as Number, penWidth as Number,
        startDegrees as Float, sweepDegrees as Float
    ) as Void {
        if (radius <= 0) { return; }

        // drawArc takes whole degrees and draws a COMPLETE CIRCLE when start
        // and end are equal.  So the decision is made on the whole-degree
        // sweep, not the Float one: rounding start and end separately let a
        // sub-degree progress fill (a few steps into the day) truncate to
        // start == end and paint the whole ring in the fill colour.
        var sweep = roundAway(sweepDegrees);
        if (sweep == 0) { return; }
        if (sweep > 360) { sweep = 360; }
        if (sweep < -360) { sweep = -360; }

        // Garmin's degrees increase counter-clockwise (0 is 3 o'clock, 90 is
        // 12 o'clock), so an author's clockwise sweep *subtracts* from the start
        // angle and travels in the ARC_CLOCKWISE direction.
        var start = roundAway(startDegrees) % 360;
        if (start < 0) { start += 360; }
        var end = (start - sweep) % 360;
        if (end < 0) { end += 360; }
        // |sweep| == 360 lands end back on start: the one case where the full
        // circle is what the author asked for.
        var direction = (sweep > 0)
            ? Graphics.ARC_CLOCKWISE
            : Graphics.ARC_COUNTER_CLOCKWISE;

        dc.setPenWidth(penWidth);
        dc.drawArc(cx, cy, radius, direction, start, end);
        dc.setPenWidth(1);
    }

    //! Round half away from zero.  `toNumber` alone truncates towards zero,
    //! which would make a clockwise and an anticlockwise sweep of the same
    //! size round differently.
    function roundAway(degrees as Float) as Number {
        return (degrees < 0.0)
            ? (degrees - 0.5).toNumber()
            : (degrees + 0.5).toNumber();
    }
}

WfbColor.mc:
import Toybox.Lang;

//! Colour arithmetic for the generated view.
module WfbColor {

    //! Scale one packed 0xRRGGBB colour's channels by num/den, rounded to
    //! the nearest integer, for the AOD frame's `aod: {dim: ...}`
    //! (docs/guide/always-on-display.md).
    //!
    //! Used only for a colour whose value is not known at build time -- a
    //! `config.colors.<role>` field read, or a conditional between several
    //! colours -- so the ternary at the call site can dim it. A
    //! build-time-constant colour (a bare hex literal, or a `palette.<name>`
    //! reference) is never routed through this call at all: it is
    //! pre-dimmed into a second literal in Python instead
    //! (`dimColorCode` in ts/src/emit/monkeyc/common.ts), because there is nothing
    //! left to compute once the device is running.
    //!
    //! Plain integer arithmetic throughout, never a Float: ts/src/palette.ts
    //! computes this exact formula for the build-time half, and the
    //! preview for the host-rendered half, and
    //! all three must agree bit for bit. A channel times `dim` landing near
    //! a `.5` boundary would be free to round differently under Python's
    //! banker's rounding, this platform's own `Math.round`, and 32-bit vs.
    //! 64-bit float precision -- integer division sidesteps all three, and
    //! this platform's `/` between two non-negative `Number`s truncates
    //! toward zero exactly like Python's `//` does for the same operands.
    function dim(color as Number, num as Number, den as Number) as Number {
        var r = (((color >> 16) & 0xFF) * num + den / 2) / den;
        var g = (((color >> 8) & 0xFF) * num + den / 2) / den;
        var b = ((color & 0xFF) * num + den / 2) / den;
        return ((r & 0xFF) << 16) | ((g & 0xFF) << 8) | (b & 0xFF);
    }
}

WfbComplications.mc:
import Toybox.Lang;
import Toybox.Complications;
import Toybox.System;

//! Every `complication.*` source is read by *pull*, not delivered by a
//! callback: `valueOf` below is called fresh from `onUpdate` (and
//! `onPartialUpdate`) every frame, the same ordinary way every other reader
//! in the catalogue is called. There is nothing cached in this module or in
//! the generated view -- see docs/research/probes/complication-pull/, which
//! confirmed a pull needs no prior subscription at all: the SDK's own
//! `ConfigurableWatchFace` sample calls `Complications.getComplication(id)`
//! from `updateConfiguration`, which runs in `onLayout` *before* the first
//! `subscribeToUpdates`, and again in edit mode where it never subscribes.
//!
//! `subscribe` is kept anyway, and is not caching: it exists only so the
//! *platform's own* reading for a type stays current between pulls. Whether
//! a pull with no subscription at all would also stay fresh is genuinely
//! unverified here -- the simulator does not run in this sandbox (CLAUDE.md
//! §6 finding 11) -- so the subscription is cheap insurance against a value
//! that silently never updates, which is exactly the failure class this
//! project exists to eliminate. It costs one line per bound type in
//! `onLayout` and nothing per frame.
//!
//! Both `subscribe` and `valueOf` can fail simply because this hardware does
//! not support the type -- a device's own ConnectIQ ceiling can sit below a
//! complication's `Since` level; see ts/src/data/catalog.json's `activity.sleep_score`
//! for a concrete case -- and Toybox/Complications.html documents the failure
//! two different ways depending on the call: `subscribeToUpdates` returns
//! `false` if the type could not be subscribed to, or throws
//! `ComplicationNotFoundException` if it was not found at all; `getComplication`
//! only ever throws. One place absorbs both outcomes uniformly, so neither the
//! generated `onLayout` subscription loop nor a bound element's `onUpdate`
//! read needs to know which of the two ways a given device declines a given
//! type -- the value a pull returns simply stays `null`, the same "absence is
//! normal" contract every other nullable source in this catalogue already
//! has. `subscribe`'s `false` return is not "caught" in any active sense --
//! there is nothing to catch, it is a plain return value -- it is simply
//! discarded, which is the correct handling here: a `false` and a caught
//! exception leave the device in the exact same state (never subscribed,
//! every pull still returns null), so there is nothing a `false` branch would
//! do differently.
module WfbComplications {

    function subscribe(id as Complications.Id) as Void {
        try {
            Complications.subscribeToUpdates(id);
        } catch (ex instanceof Complications.ComplicationNotFoundException) {
            System.println("wfb: complication not available on this device: " + ex.getErrorMessage());
        }
    }

    //! The read path: called from a generated element's `onUpdate` pull, once
    //! per bound complication per frame, exactly like `ActivityMonitor.getInfo()`
    //! or `Weather.getCurrentConditions()` for any other reader. Absorbs
    //! `ComplicationNotFoundException` ("if the complication...is not found",
    //! Toybox/Complications.html, which also covers a subscribed complication
    //! that "becomes unavailable") so an unsupported or momentarily-missing
    //! type reads as `null` instead of taking the face down -- the caller
    //! treats that the same as any other absent nullable source.
    function valueOf(id as Complications.Id) as Complications.Complication? {
        try {
            return Complications.getComplication(id);
        } catch (ex instanceof Complications.ComplicationNotFoundException) {
            return null;
        }
    }

    //! A count-type complication's value, as the count itself.  A device may
    //! hand a large count over already scaled to thousands: in the simulator
    //! steps 12,569 arrive as the Float 12.569 with the String unit "K"
    //! (docs/research/24-complication-full-scale.md §5).  That case is
    //! multiplied back and rounded -- truncating `12.569 * 1000` in single
    //! precision reads one low for some counts (16,001 is the first); rounding
    //! recovers every count to 199,999.  Anything else is returned as it came.
    function count(c as Complications.Complication) as Number? {
        var value = c.value;
        var unit = c.unit;
        if (value != null && !(value instanceof Lang.String) && !(value instanceof Lang.Number)
                && unit instanceof Lang.String && unit.equals("K")) {
            return ((value as Numeric).toFloat() * 1000 + 0.5).toNumber();
        }
        return value as Number?;
    }
}

WfbGeom.mc:
import Toybox.Graphics;
import Toybox.Lang;
import Toybox.Math;

//! Shared rotate/translate-and-draw helpers for analog hands and
//! patterns, plus a pattern's `shape: text` parts.  Both
//! resolve a template's geometry once at build time, in a frame whose origin
//! is the axis (a hand) or the pattern's own `at:` (a pattern's template,
//! copy 0 as authored) -- and leave only the per-frame transform to the
//! watch: rotation for a hand or a radial pattern, translation for a linear
//! one.  A text part is the one shape whose *glyphs* never turn -- a bitmap
//! font cannot rotate -- so only its anchor point goes through the rotation;
//! `drawTextRotated` is `dc.drawText` with that same rotate-the-point step in
//! front of it.  Moved out of WfbHands.mc when patterns needed the same four
//! calls ("one convention, one helper", the precedent
//! WfbArc.mc already set for arcs) -- WfbHands.mc keeps only the three
//! clock-to-angle functions.
//!
//! Rotating clockwise by theta on a y-down screen:
//!     x' = x cos(theta) - y sin(theta)
//!     y' = x sin(theta) + y cos(theta)
//! the same transform as the SDK's own Analog sample
//! ($CIQ_SDK/samples/Analog/source/AnalogView.mc, generateHandCoordinates),
//! and verified against a real build in
//! docs/research/probes/analog-hands/, which this file started from.
//!
//! `sin`/`cos` are typed `Decimal` (`Float or Double`), not `Float` --
//! `Math.sin`/`Math.cos` are declared to return that union, and a
//! `Float`-typed parameter fails strict typing (docs/lore/monkeyc.md).
module WfbGeom {

    //! A polygon part (a rectangle part is already folded into one at build
    //! time): rotate every vertex about the centre, then fill.
    function fillRotated(dc as Dc, points as Array<Graphics.Point2D>,
                         cx as Number, cy as Number,
                         sin as Decimal, cos as Decimal) as Void {
        var n = points.size();
        var out = new Array<Graphics.Point2D>[n];
        for (var i = 0; i < n; i++) {
            var p = points[i];
            var x = p[0];
            var y = p[1];
            out[i] = [cx + x * cos - y * sin, cy + x * sin + y * cos];
        }
        dc.fillPolygon(out);
    }

    //! A line part: rotate both endpoints; the pen width is the caller's.
    function drawLineRotated(dc as Dc, x1 as Number, y1 as Number,
                             x2 as Number, y2 as Number,
                             cx as Number, cy as Number,
                             sin as Decimal, cos as Decimal) as Void {
        dc.drawLine(cx + x1 * cos - y1 * sin, cy + x1 * sin + y1 * cos,
                    cx + x2 * cos - y2 * sin, cy + x2 * sin + y2 * cos);
    }

    //! A filled circle part: only its centre moves; a circle is its own
    //! rotation.
    function fillCircleRotated(dc as Dc, x as Number, y as Number, r as Number,
                               cx as Number, cy as Number,
                               sin as Decimal, cos as Decimal) as Void {
        dc.fillCircle(cx + x * cos - y * sin, cy + x * sin + y * cos, r);
    }

    //! An outlined circle part (`filled: false`).  The caller sets the pen
    //! width around this call, the same convention every other outlined
    //! shape in this project follows.
    function drawCircleRotated(dc as Dc, x as Number, y as Number, r as Number,
                               cx as Number, cy as Number,
                               sin as Decimal, cos as Decimal) as Void {
        dc.drawCircle(cx + x * cos - y * sin, cy + x * sin + y * cos, r);
    }

    //! A polygon part in a *linear* pattern: no rotation, just
    //! translate every vertex by the current copy's own origin.  A hand
    //! never calls this -- only a linear pattern ever translates rather than
    //! rotates.
    function fillTranslated(dc as Dc, points as Array<Graphics.Point2D>,
                            ox as Number, oy as Number) as Void {
        var n = points.size();
        var out = new Array<Graphics.Point2D>[n];
        for (var i = 0; i < n; i++) {
            var p = points[i];
            out[i] = [ox + p[0], oy + p[1]];
        }
        dc.fillPolygon(out);
    }

    //! A text part: rotate only the anchor -- the glyphs stay
    //! upright, a bitmap font cannot turn -- round it half up, then draw.
    //!
    //! **Round half up, not `(v + 0.5).toNumber()` alone**:
    //! `.toNumber()` truncates toward zero
    //! (`WfbArc.roundAway`'s own docstring), which disagrees with `Math.
    //! floor` for a negative `v + 0.5` that is not itself a whole number --
    //! e.g. `v = -1.6`: `floor(-1.1) == -2` but `(-1.1).toNumber() == -1`.
    //! A rotated/translated anchor can legitimately land off the top or
    //! left edge of the screen (an author-placed or lint-flagged, not
    //! build-rejected, case -- `docs/limitations.md`'s "off-screen" lint is
    //! suppressible, not a hard error), so this is reachable on a real
    //! design, not merely a theoretical corner. `patternTextAnchor`
    //! (ts/src/kinds/pattern.ts), the preview's own twin, uses
    //! `math.floor(v + 0.5)`; without this the two disagree by one pixel
    //! for exactly the negative, non-half-integer inputs above, and the
    //! device draws one pixel off from what `wfb preview` shows.
    //!
    //! **Why the point is rotated separately:** a single combined
    //! `drawTextRotated(dc, x, y, cx, cy, sin, cos, font, text, justify)`
    //! is 10 parameters wide, and
    //! CIQ 3.x rejects a function past 9 outright ("Too many arguments
    //! passed to method 'drawTextRotated'. Only 9 arguments are allowed.",
    //! seen on fenix6/fenix6xpro/fr245 -- `docs/lore/monkeyc.md`). Folding
    //! `cx`/`cy` or `sin`/`cos` into one argument would not help: either
    //! shape needs a fresh two-element array (a `Point2D` or similar) built *inside* this pattern's per-copy draw
    //! loop, which every other helper in this file avoids by taking plain
    //! `Number`/`Decimal` scalars. Splitting the rotate-the-point step from
    //! the draw keeps every argument a scalar and adds no allocation: the
    //! caller (ts/src/emit/monkeyc/rotated.ts) passes `rotatedX`/`rotatedY`'s
    //! results straight into `dc.drawText` as its own `x`/`y`, exactly the
    //! anchor this used to compute internally. Each axis still rounds half
    //! up, matching `patternTextAnchor`'s per-axis `Math.floor(v +
    //! 0.5)` pixel for pixel (see the "Round half up" note
    //! above for the `Math.floor` fix that makes this actually true for a
    //! negative anchor too), so the preview and the device still agree.
    //!
    //! `text` is typed `String` rather than `drawText`'s own wider `Object`
    //! because every caller here already has a `String`, from a literal or
    //! from ts/src/formatting.ts's `emit`'s own `.format(...)`/`.toString()` output
    //! (`docs/lore/monkeyc.md`'s narrowest-type rule).  `justify` keeps
    //! `Dc.drawText`'s own union type: a bitwise-OR'd pair of
    //! `Graphics.TEXT_JUSTIFY_*` flags typechecks as `Lang.Number`, not
    //! `Graphics.TextJustification`, under `-l 3`.
    function rotatedX(x as Number, y as Number, cx as Number,
                      sin as Decimal, cos as Decimal) as Number {
        return Math.floor(cx + x * cos - y * sin + 0.5).toNumber();
    }

    function rotatedY(x as Number, y as Number, cy as Number,
                      sin as Decimal, cos as Decimal) as Number {
        return Math.floor(cy + x * sin + y * cos + 0.5).toNumber();
    }
}

WfbHands.mc:
//! Analog hands: convert the current time into each hand's own
//! rotation angle.
//!
//! Drawing itself -- turning a hand's build-time-resolved geometry by that
//! angle, or (for a pattern) turning or translating a template's --
//! lives in WfbGeom.mc, the "one convention, one helper" precedent WfbArc.mc
//! already set for arcs.

import Toybox.Lang;
import Toybox.Math;
import Toybox.System;

module WfbHands {

    //! Hour hand: 30 degrees an hour plus half a degree a minute, so it sits
    //! between numerals at half past rather than jumping on the hour.
    function hourAngle(clock as System.ClockTime) as Float {
        return ((clock.hour % 12) * 60 + clock.min) * (Math.PI / 360.0);
    }

    //! Minute hand: whole minutes, 6 degrees each.
    function minuteAngle(clock as System.ClockTime) as Float {
        return clock.min * (Math.PI / 30.0);
    }

    //! Second hand: whole seconds, 6 degrees each.
    function secondAngle(clock as System.ClockTime) as Float {
        return clock.sec * (Math.PI / 30.0);
    }
}

WfbMath.mc:
import Toybox.Lang;

//! The expression language's function set.
//!
//! These exist as functions rather than being inlined by the generator because
//! inlining `clamp(x, 0, 100)` would evaluate `x` three times.  Expressions are
//! pure, so that would be correct -- but it triples the generated text and makes
//! the output unreadable, which ADR 0003 does not allow.
module WfbMath {

    //! The smaller of two numbers.
    function min(a as Numeric, b as Numeric) as Numeric {
        return (a < b) ? a : b;
    }

    //! The larger of two numbers.
    function max(a as Numeric, b as Numeric) as Numeric {
        return (a > b) ? a : b;
    }

    //! Constrain a value to the inclusive range [lo, hi].
    function clamp(value as Numeric, lo as Numeric, hi as Numeric) as Numeric {
        if (value < lo) { return lo; }
        if (value > hi) { return hi; }
        return value;
    }

    //! Absolute value.
    function abs(value as Numeric) as Numeric {
        return (value < 0) ? -value : value;
    }

    //! `a / b` as a Float, or 0.0 when `b` is zero.
    //!
    //! An expression's `/` with a divisor read at run time: a reading can be
    //! zero (a sensor at rest, an unset goal), and the face must not divide
    //! by it. `monkeyc` refuses a literal zero divisor outright.
    function div(a as Numeric, b as Numeric) as Float {
        if (b == 0) { return 0.0; }
        return a.toFloat() / b.toFloat();
    }

    //! `a % b`, or 0 when `b` is zero -- `div`'s guard, for the remainder.
    function mod(a as Number, b as Number) as Number {
        if (b == 0) { return 0; }
        return a % b;
    }

    //! `value` as a percentage of `goal`, clamped to 0..100.
    //!
    //! A zero or negative goal yields 0 rather than dividing by zero: a goal of
    //! zero is a real reading on this platform (an unset step goal), not a bug.
    function percent(value as Numeric, goal as Numeric) as Float {
        if (goal <= 0) { return 0.0; }
        var pct = 100.0 * value.toFloat() / goal.toFloat();
        return clamp(pct, 0.0, 100.0) as Float;
    }
}

WfbProfileScale.mc:
import Toybox.Complications;
import Toybox.Lang;
import Toybox.Time;
import Toybox.Time.Gregorian;
import Toybox.UserProfile;

//! The parts of a gauge's automatic scale that read the wearer's profile:
//! their heart-rate zones and their VO2 max row.  Kept apart from `WfbScale`
//! because `monkeyc` refuses any reference to `Toybox.UserProfile` without
//! the `UserProfile` permission, and the barrel ships only the modules the
//! generated code names: a face whose gauges cannot show heart rate or VO2
//! max ships none of this, and declares no permission for it.
module WfbProfileScale {

    //! The wearer's own heart-rate zones: zone 1's minimum to zone 5's
    //! maximum (`getHeartRateZones` returns the minimum, then each zone's top).
    function heartRate() as Array<Numeric>? {
        var zones = UserProfile.getHeartRateZones(UserProfile.HR_ZONE_SPORT_GENERIC);
        if (zones.size() < 6 || zones[0] >= zones[5]) {
            return null;
        }
        return [zones[0], zones[5]] as Array<Numeric>;
    }

    //! The ends of the wearer's VO2 max row.  `ends` holds the female rows
    //! then the male rows, ages 20-29 to 70-79, each a minimum then a
    //! maximum.  Null without a birth year, or a sex the table has, or with
    //! an age outside 20-79; the age is this year less the birth year, so it
    //! can read one year high until the birthday.  Null too while `c` reads
    //! 0, which is how a watch reports no VO2 max recorded.
    function vo2max(ends as Array<Float>, c as Complications.Complication) as Array<Numeric>? {
        var value = c.value;
        if (value instanceof Lang.Number && value == 0) {
            return null;
        }
        var profile = UserProfile.getProfile();
        var gender = profile.gender;
        var born = profile.birthYear;
        if (gender == null || born == null) {
            return null;
        }
        var first;
        if (gender == UserProfile.GENDER_FEMALE) {
            first = 0;
        } else if (gender == UserProfile.GENDER_MALE) {
            first = 6;
        } else {
            return null;
        }
        var age = Gregorian.info(Time.now(), Time.FORMAT_SHORT).year - born;
        if (age < 20 || age > 79) {
            return null;
        }
        var i = (first + (age - 20) / 10) * 2;
        return [ends[i], ends[i + 1]] as Array<Numeric>;
    }
}

WfbReading.mc:
import Toybox.Lang;
import Toybox.Complications;

//! A `data` element's reading as display text: the arithmetic behind the
//! generated `SlotText.reading`, which picks one of these per complication
//! type.  Each function has a host twin in ts/src/complications.ts
//! (`formatReading` and its helpers), which the preview draws with.
//!
//! Only the slot calls these, so a face that reads `complication.*` through
//! an ordinary `text` element does not carry them.
module WfbReading {

    //! A pulled value with no per-type rule: a Number, Long or String
    //! through `toString()`, a Float or Double through `decimalText`, because
    //! `Float.toString()` always prints six decimals.
    function formatValue(value as Complications.Value) as String {
        if (value instanceof Lang.Float) {
            return decimalText(value.toDouble());
        }
        if (value instanceof Lang.Double) {
            return decimalText(value);
        }
        return value.toString();
    }

    //! Three significant figures without ever dropping an integer digit,
    //! then trailing zeros removed: 12.879 -> "12.9", 9.876 -> "9.88",
    //! 21.5 -> "21.5", 101325.0 -> "101325", 10.0 -> "10".
    function decimalText(value as Lang.Double) as String {
        var magnitude = (value < 0) ? -value : value;
        var decimals = 2;
        if (magnitude >= 100) {
            decimals = 0;
        } else if (magnitude >= 10) {
            decimals = 1;
        }
        var text = value.format("%." + decimals + "f");
        if (decimals == 0) {
            return text;
        }
        var chars = text.toCharArray();
        var keep = chars.size();
        while (keep > 0 && chars[keep - 1] == '0') {
            keep -= 1;
        }
        if (keep > 0 && chars[keep - 1] == '.') {
            keep -= 1;
        }
        var trimmed = text.substring(0, keep);
        return (trimmed != null) ? trimmed : text;
    }

    //! `Complication.unit` as a suffix, for a type with no rule of its own
    //! (an app's complication): a String is used as written, the SDK's
    //! `Unit` enum through its documented meaning, anything else as "".
    //! `UNIT_SUFFIX` in ts/src/complications.ts is the host twin.
    function unitSuffix(unit as Complications.Unit or Lang.String or Null) as String {
        if (unit == null) {
            return "";
        }
        if (unit instanceof Lang.String) {
            return unit;
        }
        switch (unit) {
            case Complications.UNIT_DISTANCE: return "m";
            case Complications.UNIT_ELEVATION: return "m";
            case Complications.UNIT_HEIGHT: return "m";
            case Complications.UNIT_SPEED: return "m/s";
            case Complications.UNIT_TEMPERATURE: return "°C";
            case Complications.UNIT_WEIGHT: return "g";
            default: return "";
        }
    }

    //! Nearest whole number, halves away from zero.
    function rounded(value as Numeric) as Number {
        var real = value.toDouble();
        if (real < 0) {
            return -((-real + 0.5).toNumber());
        }
        return (real + 0.5).toNumber();
    }

    //! A count.  The device may already have scaled it to thousands (seen in
    //! the simulator: steps past 10,000 arrive as the Float 12.879 with the
    //! unit "K"), so a String unit on a Float is kept; a whole count of
    //! 10,000 or more is scaled here the same way.  Thousands always carry
    //! one decimal, "10.0K" as well as "12.9K", so the reading keeps its
    //! shape as the count grows.
    function count(value as Numeric, unit as Complications.Unit or Lang.String or Null) as String {
        if (value instanceof Lang.Float || value instanceof Lang.Double) {
            if (unit instanceof Lang.String && unit.equals("K")) {
                return value.format("%.1f") + "K";
            }
            return decimalText(value.toDouble()) + ((unit instanceof Lang.String) ? unit : "");
        }
        var whole = value.toNumber();
        if (whole >= 10000 || whole <= -10000) {
            return (whole.toDouble() / 1000.0d).format("%.1f") + "K";
        }
        return whole.toString();
    }

    //! Seconds since local midnight as the clock the wearer reads: "06:15"
    //! or "18:12" on a 24-hour watch, "6:15" and "6:12" on a 12-hour one.
    function clock(seconds as Numeric, is24Hour as Boolean) as String {
        var minutes = (seconds.toNumber() / 60) % 1440;
        if (minutes < 0) {
            minutes += 1440;
        }
        var hour = minutes / 60;
        var shown = is24Hour ? hour.format("%02d") : ((hour % 12 == 0) ? 12 : hour % 12).toString();
        return shown + ":" + (minutes % 60).format("%02d");
    }

    //! Seconds as a duration: "24:40", or "1:43:12" from an hour up.
    function duration(seconds as Numeric) as String {
        var total = seconds.toNumber();
        if (total < 0) {
            total = 0;
        }
        var hours = total / 3600;
        var tail = ((total / 60) % 60).format(hours > 0 ? "%02d" : "%d") + ":" + (total % 60).format("%02d");
        return (hours > 0) ? hours + ":" + tail : tail;
    }

    //! Minutes as whole hours, rounded up so that time still left never reads
    //! as none: 1 minute is "1h", 0 is "0h".
    function hours(minutes as Numeric) as String {
        var total = minutes.toNumber();
        if (total < 0) {
            total = 0;
        }
        return ((total + 59) / 60) + "h";
    }

    //! `number` then `suffix`, unless `short` and the two together would pass
    //! seven characters: then the number alone.
    function suffixed(number as String, suffix as String, short as Boolean) as String {
        if (short && number.length() + suffix.length() > 7) {
            return number;
        }
        return number + suffix;
    }

    //! A percentage: bare, or "%" after it with `unit`.
    function percent(value as Numeric, unit as Boolean) as String {
        return rounded(value).toString() + (unit ? "%" : "");
    }

    //! Degrees Celsius, in Fahrenheit when `statute`, always with "°", and
    //! "°C"/"°F" with `unit`: "24°", "24°C".
    function temperature(celsius as Numeric, statute as Boolean, unit as Boolean) as String {
        var degrees = statute ? celsius.toDouble() * 1.8d + 32.0d : celsius.toDouble();
        return rounded(degrees).toString() + (unit ? (statute ? "°F" : "°C") : "°");
    }

    //! An elevation in metres as whole metres or, when `statute`, feet.
    function elevation(metres as Numeric, statute as Boolean, unit as Boolean,
                       short as Boolean) as String {
        var shown = statute ? metres.toDouble() / 0.3048d : metres.toDouble();
        return suffixed(rounded(shown).toString(), unit ? (statute ? "ft" : "m") : "", short);
    }

    //! A distance in metres as kilometres or, when `statute`, miles, to one
    //! decimal: "12.3".
    function distance(metres as Numeric, statute as Boolean, unit as Boolean,
                      short as Boolean) as String {
        var shown = metres.toDouble() / (statute ? 1609.344d : 1000.0d);
        return suffixed(shown.format("%.1f"), unit ? (statute ? "mi" : "km") : "", short);
    }

    //! Pascals as whole hectopascals: 101675 -> "1017".
    function pressure(pascals as Numeric, unit as Boolean, short as Boolean) as String {
        return suffixed(rounded(pascals.toDouble() / 100.0d).toString(), unit ? "hPa" : "", short);
    }

    //! A speed in metres per second as a pace per kilometre or, when
    //! `statute`, per mile: "4:56", "4:56/km".  Null for a speed of zero,
    //! which has no pace.
    function pace(speed as Numeric, statute as Boolean, unit as Boolean,
                  short as Boolean) as String? {
        var mps = speed.toDouble();
        if (mps <= 0) {
            return null;
        }
        var seconds = rounded((statute ? 1609.344d : 1000.0d) / mps);
        return suffixed(duration(seconds), unit ? (statute ? "/mi" : "/km") : "", short);
    }

    //! "H 26 / L 17" as "26/17": the first two whole numbers in the text,
    //! each with its minus sign.  Text that does not hold exactly two is
    //! returned unchanged.
    function highLowShort(text as String) as String {
        var found = [] as Array<String>;
        var current = "";
        var chars = text.toCharArray();
        for (var i = 0; i <= chars.size(); i++) {
            var code = (i < chars.size()) ? chars[i].toNumber() : 0;
            if (code >= 48 && code <= 57) {
                current += chars[i].toString();
            } else if (code == 45 && current.length() == 0) {
                current = "-";
            } else {
                if (current.length() > 0 && !current.equals("-")) {
                    found.add(current);
                }
                current = "";
            }
        }
        if (found.size() != 2) {
            return text;
        }
        return found[0] + "/" + found[1];
    }

    //! Entry `index` of `names`, a table of entries padded with "|" to
    //! `width` characters each; an index outside it reads as the last entry.
    //! One string in place of a `switch` over every entry, which costs far
    //! more code.
    function packed(names as String, width as Number, index as Number) as String {
        var count = names.length() / width;
        if (index < 0 || index >= count) {
            index = count - 1;
        }
        var entry = names.substring(index * width, index * width + width);
        if (entry == null) {
            return "";
        }
        var end = entry.find("|");
        var name = (end != null) ? entry.substring(0, end) : entry;
        return (name != null) ? name : entry;
    }

    //! `short` in the case `reported` uses: all capitals when the device
    //! reported all capitals ("MAINTAINING" -> "MAINT"), as written otherwise.
    function inCaseOf(short as String, reported as String) as String {
        return reported.equals(reported.toUpper()) ? short.toUpper() : short;
    }
}

WfbRing.mc:
import Toybox.Graphics;
import Toybox.Lang;

//! A 1px `outline:` ring for a polygon, line or outlined circle (research
//! 19): the part transformed **once**, then drawn at the four points one
//! pixel away (`discPerimeterOffsets(1)`, in its order).  A wider
//! ring is `WfbRingWide`'s.  Its own module, apart
//! from `WfbGeom`, so a face that draws no ring compiles none of it -- the
//! barrel copies in only the modules the generated code calls
//! (`barrelModules` in ts/src/emit/usage.ts).
//!
//! Rotation is `WfbGeom`'s own (`x' = x cos - y sin`, `y' = x sin + y cos`).
module WfbRing {

    //! A polygon part's 1px `outline:` ring: the four fills
    //! one pixel left, up, down and right of it.  Rotates the vertices
    //! once and shifts that one array between fills, where a stamp through
    //! `WfbGeom.fillRotated` would rotate and allocate a fresh array per offset --
    //! measured on a fenix 8 at twice the cost of the fills themselves
    //! (research 19 §4.5).
    function rotated(dc as Dc, points as Array<Graphics.Point2D>,
                     cx as Number, cy as Number,
                     sin as Decimal, cos as Decimal) as Void {
        var n = points.size();
        var out = new Array<Graphics.Point2D>[n];
        for (var i = 0; i < n; i++) {
            var p = points[i];
            var x = p[0];
            var y = p[1];
            out[i] = [cx + x * cos - y * sin, cy + x * sin + y * cos];
        }
        polygon(dc, out);
    }

    //! `rotated` for a linear pattern's (or a shape's own) polygon:
    //! translated by `(ox, oy)` instead of rotated.
    function translated(dc as Dc, points as Array<Graphics.Point2D>,
                        ox as Number, oy as Number) as Void {
        var n = points.size();
        var out = new Array<Graphics.Point2D>[n];
        for (var i = 0; i < n; i++) {
            var p = points[i];
            out[i] = [ox + p[0], oy + p[1]];
        }
        polygon(dc, out);
    }

    //! Fill ``out`` at the four offsets, shifting it in place: (-1, 0),
    //! (0, -1), (0, 1), (1, 0) -- `discPerimeterOffsets(1)`'s order.
    function polygon(dc as Dc, out as Array<Graphics.Point2D>) as Void {
        shift(out, -1, 0);
        dc.fillPolygon(out);
        shift(out, 1, -1);
        dc.fillPolygon(out);
        shift(out, 0, 2);
        dc.fillPolygon(out);
        shift(out, 1, -1);
        dc.fillPolygon(out);
    }

    function shift(out as Array<Graphics.Point2D>, dx as Number, dy as Number) as Void {
        for (var i = 0; i < out.size(); i++) {
            var p = out[i];
            p[0] = p[0] + dx;
            p[1] = p[1] + dy;
        }
    }

    //! A line part's 1px ring: both ends rotated once, then four lines one
    //! pixel off; the pen width is the caller's.
    function lineRotated(dc as Dc, x1 as Number, y1 as Number,
                         x2 as Number, y2 as Number,
                         cx as Number, cy as Number,
                         sin as Decimal, cos as Decimal) as Void {
        var ax = cx + x1 * cos - y1 * sin;
        var ay = cy + x1 * sin + y1 * cos;
        var bx = cx + x2 * cos - y2 * sin;
        var by = cy + x2 * sin + y2 * cos;
        dc.drawLine(ax - 1, ay, bx - 1, by);
        dc.drawLine(ax, ay - 1, bx, by - 1);
        dc.drawLine(ax, ay + 1, bx, by + 1);
        dc.drawLine(ax + 1, ay, bx + 1, by);
    }

    //! An outlined circle part's 1px ring: the centre rotated once, then
    //! four circles one pixel off; the pen width is the caller's.
    function circleRotated(dc as Dc, x as Number, y as Number, r as Number,
                           cx as Number, cy as Number,
                           sin as Decimal, cos as Decimal) as Void {
        var px = cx + x * cos - y * sin;
        var py = cy + x * sin + y * cos;
        dc.drawCircle(px - 1, py, r);
        dc.drawCircle(px, py - 1, r);
        dc.drawCircle(px, py + 1, r);
        dc.drawCircle(px + 1, py, r);
    }

}

WfbRingWide.mc:
import Toybox.Graphics;
import Toybox.Lang;

//! A 2px or 3px `outline:` ring for a polygon, line or outlined circle
//! (research 19): `WfbRing`'s 1px functions, walking the build's
//! `Layout.OUTLINE_OFFSETS_<W>` table (`discPerimeterOffsets`) for
//! the points instead of spelling four out.  Its own module, so a face
//! whose rings are all 1px compiles none of it.
//!
//! Rotation is `WfbGeom`'s own (`x' = x cos - y sin`, `y' = x sin + y cos`).
module WfbRingWide {

    //! A polygon part's ring: rotated once, then filled at every ``offsets``
    //! point (flat `[dx0, dy0, dx1, dy1, ...]`).
    function rotated(dc as Dc, points as Array<Graphics.Point2D>,
                     cx as Number, cy as Number,
                     sin as Decimal, cos as Decimal,
                     offsets as Array<Number>) as Void {
        var n = points.size();
        var out = new Array<Graphics.Point2D>[n];
        for (var i = 0; i < n; i++) {
            var p = points[i];
            var x = p[0];
            var y = p[1];
            out[i] = [cx + x * cos - y * sin, cy + x * sin + y * cos];
        }
        polygon(dc, out, offsets);
    }

    //! `rotated` for a linear pattern's polygon: translated by `(ox, oy)`.
    function translated(dc as Dc, points as Array<Graphics.Point2D>,
                        ox as Number, oy as Number,
                        offsets as Array<Number>) as Void {
        var n = points.size();
        var out = new Array<Graphics.Point2D>[n];
        for (var i = 0; i < n; i++) {
            var p = points[i];
            out[i] = [ox + p[0], oy + p[1]];
        }
        polygon(dc, out, offsets);
    }

    //! Fill ``out`` at every ``offsets`` point, shifting it in place from
    //! one point to the next.
    function polygon(dc as Dc, out as Array<Graphics.Point2D>,
                     offsets as Array<Number>) as Void {
        var px = 0;
        var py = 0;
        for (var i = 0; i < offsets.size(); i += 2) {
            shift(out, offsets[i] - px, offsets[i + 1] - py);
            px = offsets[i];
            py = offsets[i + 1];
            dc.fillPolygon(out);
        }
    }

    //! A line part's ring: both ends rotated once, then one line per point;
    //! the pen width is the caller's.  The line's ends come as one
    //! `[x1, y1, x2, y2]`, keeping the call within the nine parameters a
    //! barrel function may take.
    function lineRotated(dc as Dc, ends as Array<Number>,
                         cx as Number, cy as Number,
                         sin as Decimal, cos as Decimal,
                         offsets as Array<Number>) as Void {
        var x1 = ends[0];
        var y1 = ends[1];
        var x2 = ends[2];
        var y2 = ends[3];
        var ax = cx + x1 * cos - y1 * sin;
        var ay = cy + x1 * sin + y1 * cos;
        var bx = cx + x2 * cos - y2 * sin;
        var by = cy + x2 * sin + y2 * cos;
        for (var i = 0; i < offsets.size(); i += 2) {
            var dx = offsets[i];
            var dy = offsets[i + 1];
            dc.drawLine(ax + dx, ay + dy, bx + dx, by + dy);
        }
    }

    //! An outlined circle part's ring: the centre rotated once, then one
    //! circle per point; the pen width is the caller's.
    function circleRotated(dc as Dc, x as Number, y as Number, r as Number,
                           cx as Number, cy as Number,
                           sin as Decimal, cos as Decimal,
                           offsets as Array<Number>) as Void {
        var px = cx + x * cos - y * sin;
        var py = cy + x * sin + y * cos;
        for (var i = 0; i < offsets.size(); i += 2) {
            dc.drawCircle(px + offsets[i], py + offsets[i + 1], r);
        }
    }

    function shift(out as Array<Graphics.Point2D>, dx as Number, dy as Number) as Void {
        for (var i = 0; i < out.size(); i++) {
            var p = out[i];
            p[0] = p[0] + dx;
            p[1] = p[1] + dy;
        }
    }

}

WfbScale.mc:
import Toybox.Complications;
import Toybox.Lang;

//! The parts of a gauge's automatic scale that read the device: a goal, an
//! app complication's own `ranges`, and the fill.  Each scale returns
//! `[minimum, maximum]`, or null when the device has nothing to scale by,
//! which hides the gauge.  The figures themselves are generated into
//! `SlotScale` from the complication table's scales.  What reads the wearer's
//! profile is `WfbProfileScale`, a module of its own so a face that never
//! scales by it needs no `UserProfile` permission.
module WfbScale {

    //! 0 to a goal, or null while the goal is unset.
    function upTo(goal as Number?) as Array<Numeric>? {
        if (goal == null || goal <= 0) {
            return null;
        }
        return [0, goal] as Array<Numeric>;
    }

    //! How full a gauge on `scale` is for the pulled `c`, 0.0 to 1.0, or null
    //! while it has no numeric reading.  A count the device scaled to
    //! thousands (the String unit "K") is multiplied back first.
    function fraction(c as Complications.Complication, scale as Array<Numeric>) as Float? {
        var value = c.value;
        if (value == null || value instanceof Lang.String) {
            return null;
        }
        var reading = value.toFloat();
        var unit = c.unit;
        if (!(value instanceof Lang.Number) && unit instanceof Lang.String && unit.equals("K")) {
            reading = reading * 1000;
        }
        return share(reading, scale);
    }

    //! How full a gauge on `scale` is for a reading already in the scale's
    //! units, 0.0 to 1.0.
    function share(reading as Numeric, scale as Array<Numeric>) as Float {
        var low = scale[0].toFloat();
        var full = (reading.toFloat() - low) / (scale[1].toFloat() - low);
        if (full < 0.0) {
            return 0.0;
        }
        return (full > 1.0) ? 1.0 : full;
    }

    //! An app complication's own `ranges`, first value to last.  Garmin's
    //! native types leave `ranges` null.
    function ranges(c as Complications.Complication) as Array<Numeric>? {
        var r = c.ranges;
        if (r == null || r.size() < 2) {
            return null;
        }
        var last = r[r.size() - 1];
        if (r[0] >= last) {
            return null;
        }
        return [r[0], last] as Array<Numeric>;
    }
}

WfbSeries.mc:
import Toybox.ActivityMonitor;
import Toybox.Graphics;
import Toybox.Lang;
import Toybox.Time;

//! Time-series acquisition, binning and drawing for a `type: graph` element.
//!
//! What is fixed across every design lives here, the same split
//! `WfbArc.mc` already draws: heart-rate acquisition and
//! binning, and the generic min/max over an array, are one shape shared by
//! every graph -- Monkey C offers no way to pass a field name, so the
//! per-series array loops (`day.steps` vs. `day.calories`, `hour.temperature`
//! vs. `hour.uvIndex`) are generated per project instead, straight into the
//! view (`emitGraphRebuild` in ts/src/emit/monkeyc/graph.ts).
//!
//! Every series here is cached in a private view field and rebuilt only when
//! `System.getClockTime().min` changes -- one `Number` comparison a frame.
//! **This is not the TTL cache this project deleted** (see
//! ts/src/catalog.ts): that deletion was about re-caching a value Garmin
//! already caches on its own side (`Weather.getCurrentConditions()` is
//! documented as returning the "most recently cached" reading). A series is
//! different -- it is *this compiler's own computation* over a source whose
//! sample interval is minutes (a heart-rate bucket, a calendar day, an
//! hourly forecast slot), so recomputing it every second cannot produce any
//! new information; the cache exists to avoid paying for that computation on
//! every one of the up-to-60 frames between two minutes that could show a
//! different answer.
//!
//! **Gaps are `null`, not a sentinel number.** The reference probe
//! (`docs/research/probes/graph-series/`) marks an empty heart-rate bucket
//! `-1`; this barrel uses `null` instead, uniformly, across every series --
//! several of the forecast fields (`forecast_temperature`,
//! `daily_high_temperature`, `daily_low_temperature`) are genuinely negative
//! in Celsius, so a numeric sentinel would collide with a real reading on
//! exactly the series where getting this wrong would be least visible.
//! `Array<Float?>` costs nothing extra to check and cannot collide with data.
module WfbSeries {

    //! A line: `setPenWidth` then a `drawLine` per segment, breaking the run
    //! wherever a sample is missing rather than joining across the gap.
    function drawLine(
        dc as Graphics.Dc, x as Number, y as Number, w as Number, h as Number,
        thickness as Number, values as Array<Float?>, lo as Float, hi as Float
    ) as Void {
        var n = values.size();
        if (n < 2) { return; }
        var span = hi - lo;
        if (span <= 0.0) { span = 1.0; }
        dc.setPenWidth(thickness);
        var havePrevious = false;
        var px = 0;
        var py = 0;
        for (var i = 0; i < n; i += 1) {
            var v = values[i];
            if (v == null) { havePrevious = false; continue; }
            var cx = x + (i * w / (n - 1));
            var cy = y + h - ((v - lo) * h / span).toNumber();
            if (havePrevious) { dc.drawLine(px, py, cx, cy); }
            px = cx;
            py = cy;
            havePrevious = true;
        }
        dc.setPenWidth(1);
    }

    //! A filled area: `fillPolygon`, the only fill `Dc` offers that follows a
    //! curve -- one call per contiguous run of present samples, each closed
    //! with its own two bottom corners, rather than one call for the whole
    //! series. A single `fillPolygon` cannot represent a gap partway through
    //! its own outline without visibly joining straight across it -- there
    //! is no "lift the pen" for a filled shape -- so a gap here ends one run
    //! and starts the next, exactly as its twin `seriesArea` (ts/src/draw/barrel.ts)
    //! does for the preview, rather than
    //! either interpolating across it (a guess) or leaving the whole graph
    //! blank for one missing sample.
    //!
    //! Every individual call still respects `fillPolygon`'s own 64-point
    //! limit: a run can hold at most as many points as the whole series
    //! does, and ts/src/ir/model.ts's `GRAPH_AREA_MAX_SAMPLES` already refuses a
    //! `style: area` design whose series could exceed 62 (64 minus the two
    //! closing corners a *single* run would need).
    function drawArea(
        dc as Graphics.Dc, x as Number, y as Number, w as Number, h as Number,
        values as Array<Float?>, lo as Float, hi as Float
    ) as Void {
        var n = values.size();
        if (n < 2) { return; }
        var span = hi - lo;
        if (span <= 0.0) { span = 1.0; }
        var i = 0;
        while (i < n) {
            if (values[i] == null) { i += 1; continue; }
            var start = i;
            var end = i;
            while (end < n && values[end] != null) { end += 1; }
            var count = end - start;
            if (count >= 2) {
                // `Array<Array<Number> >` here, cast to
                // `Array<Graphics.Point2D>` at the call site below --
                // `Point2D` is a fixed-size tuple type, and a local built
                // this way is exactly what the reference probe compiles
                // warning-free (`docs/research/probes/graph-series/`,
                // `docs/research/probes/polygon-const/`).
                var run = new [count + 2] as Array<Array<Number> >;
                for (var j = 0; j < count; j += 1) {
                    var v = values[start + j];
                    var cx = x + ((start + j) * w / (n - 1));
                    // `v` is never actually null here -- `start`/`end` bound a
                    // run of indices already checked non-null above -- but
                    // the type checker narrows a local against a *repeated*
                    // read of `values[...]`, not the loop invariant, so the
                    // ternary (the same shape `ReadPlan.declarations` already
                    // relies on for a nullable intermediate) is what actually
                    // satisfies -l 3 rather than just reading intent into it.
                    var cy = (v != null) ? y + h - ((v - lo) * h / span).toNumber() : y + h;
                    run[j] = [cx, cy];
                }
                run[count] = [x + ((end - 1) * w / (n - 1)), y + h];
                run[count + 1] = [x + (start * w / (n - 1)), y + h];
                dc.fillPolygon(run as Array<Graphics.Point2D>);
            }
            i = end;
        }
    }

    //! Bars: a `fillRectangle` per bucket, `barWidth` centred in its slot.
    //! A missing sample simply draws no bar -- bars need no closing outline,
    //! so a gap here is exactly the honest "no data" the line style gives.
    function drawBars(
        dc as Graphics.Dc, x as Number, y as Number, w as Number, h as Number,
        barWidth as Number, values as Array<Float?>, lo as Float, hi as Float
    ) as Void {
        var n = values.size();
        if (n < 1) { return; }
        var span = hi - lo;
        if (span <= 0.0) { span = 1.0; }
        var pitch = w / n;
        for (var i = 0; i < n; i += 1) {
            var v = values[i];
            if (v == null) { continue; }
            var barHeight = ((v - lo) * h / span).toNumber();
            if (barHeight < 1) { barHeight = 1; }
            dc.fillRectangle(
                x + (i * pitch) + ((pitch - barWidth) / 2), y + h - barHeight,
                barWidth, barHeight
            );
        }
    }

    //! The extent of a series, ignoring gaps -- what `min: auto`/`max: auto`
    //! use for every array-backed series (heart rate uses the iterator's own
    //! `getMin`/`getMax` instead; see `binHeartRate`/`collectHeartRate`
    //! below and their call sites). `0.0`/`0.0` when every sample is
    //! missing, matching this platform's own "absence is normal" contract --
    //! the caller already clamps a non-positive span before dividing by it.
    function autoMin(values as Array<Float?>) as Float {
        var lo = 0.0;
        var have = false;
        for (var i = 0; i < values.size(); i += 1) {
            var v = values[i];
            if (v == null) { continue; }
            if (!have || v < lo) { lo = v; have = true; }
        }
        return lo;
    }

    function autoMax(values as Array<Float?>) as Float {
        var hi = 0.0;
        var have = false;
        for (var i = 0; i < values.size(); i += 1) {
            var v = values[i];
            if (v == null) { continue; }
            if (!have || v > hi) { hi = v; have = true; }
        }
        return hi;
    }

    //! Heart-rate history, binned by time -- `range:` was a duration. Average
    //! bpm per bucket, oldest bucket first (left-to-right on screen, matching
    //! `newestFirst: false`'s own left-to-right order), `null` where a bucket
    //! saw no sample. Bucket arithmetic is integer throughout except the
    //! average itself, which is computed as a `Float` deliberately -- `Number
    //! / Number` truncates on this platform (see the `activity.steps / 1000`
    //! bug this project already found and fixed elsewhere).
    function binHeartRate(
        iterator as ActivityMonitor.HeartRateIterator, buckets as Number,
        spanSeconds as Number
    ) as Array<Float?> {
        var sums = new [buckets] as Array<Number>;
        var counts = new [buckets] as Array<Number>;
        for (var i = 0; i < buckets; i += 1) {
            sums[i] = 0;
            counts[i] = 0;
        }
        var now = Time.now().value();
        while (true) {
            var sample = iterator.next();
            if (sample == null) { break; }
            var bpm = sample.heartRate;
            var when = sample.when;
            if (bpm == null || when == null) { continue; }
            if (bpm == ActivityMonitor.INVALID_HR_SAMPLE) { continue; }
            var age = now - when.value();
            if (age < 0) { age = 0; }
            if (age > spanSeconds) { continue; }
            var index = buckets - 1 - (age * buckets / spanSeconds);
            if (index < 0) { index = 0; }
            if (index >= buckets) { index = buckets - 1; }
            sums[index] = sums[index] + bpm;
            counts[index] = counts[index] + 1;
        }
        var out = new [buckets] as Array<Float?>;
        for (var i = 0; i < buckets; i += 1) {
            out[i] = (counts[i] > 0) ? (sums[i].toFloat() / counts[i]) : null;
        }
        return out;
    }

    //! Heart-rate history, raw -- `range:` was a bare sample count. No
    //! binning: a fixed count already asks for a fixed number of samples, one
    //! array slot each, oldest first.
    function collectHeartRate(iterator as ActivityMonitor.HeartRateIterator) as Array<Float?> {
        var out = [] as Array<Float?>;
        while (true) {
            var sample = iterator.next();
            if (sample == null) { break; }
            var bpm = sample.heartRate;
            if (bpm == null || bpm == ActivityMonitor.INVALID_HR_SAMPLE) { continue; }
            out.add(bpm.toFloat());
        }
        return out;
    }

    //! `min(a, b)` for a sample count against an acquired array's own size --
    //! `WfbMath.min` already exists, but this module must not assume the
    //! design bound anything that would pull `WfbMath.mc` into the barrel
    //! copy; a graph-only face needs no expression functions at all.
    function min(a as Number, b as Number) as Number {
        return (a < b) ? a : b;
    }
}

WfbTime.mc:
import Toybox.Lang;

//! Clock arithmetic that follows the user's device settings.
//!
//! `onSettingsChanged` does not fire for on-watch edits, so nothing here caches:
//! every call reads the value it was handed.  The cost is a few comparisons per
//! frame; the alternative is a face that shows 24-hour time until it is
//! restarted.
module WfbTime {

    //! A 0..23 hour as a 1..12 hour.
    function hour12(hour as Number) as Number {
        var h = hour % 12;
        return (h == 0) ? 12 : h;
    }

    //! The hour as the user has asked to see it: zero-padded 24-hour, or
    //! unpadded 12-hour.  This is the `%h` format code.
    function displayHour(hour as Number, is24Hour as Boolean) as String {
        if (is24Hour) {
            return hour.format("%02d");
        }
        return hour12(hour).format("%d");
    }

    //! "AM" or "PM" for a 0..23 hour.
    function meridiem(hour as Number) as String {
        return (hour < 12) ? "AM" : "PM";
    }

    //! One field of a duration format: the absolute value, truncated to whole
    //! seconds, in `unit`-second units, wrapped at `wrap` of them (0: not
    //! wrapped, the largest unit carrying the whole total).  Taking the
    //! absolute value first keeps `/` and `%` off negative operands, whose
    //! rounding Monkey C does not document.
    function durationPart(value as Numeric, unit as Number, wrap as Number) as Number {
        var n = value.toNumber();
        if (n < 0) {
            n = -n;
        }
        n = n / unit;
        return (wrap > 0) ? n % wrap : n;
    }

    //! "-" before a negative duration, "" otherwise.
    function durationSign(value as Numeric) as String {
        return (value.toNumber() < 0) ? "-" : "";
    }
}

WfbWeather.mc:
import Toybox.Lang;

//! Which catalogue *name* a `Toybox.Weather.CONDITION_*` value maps to, for a
//! dynamic (`icon: {for:}`) weather icon.
//!
//! The on-device twin of `GARMIN_WEATHER_CONDITION_ICON` (`ts/src/icons.ts`) -- kept
//! in sync with it deliberately (ts/test/barrel.test.ts checks the two agree,
//! name for name), not by generating this file, because the mapping is fixed
//! and shared across every design that uses `icon: {for:}`, the same reasoning
//! that keeps WfbArc.mc and WfbTime.mc hand-written.
//!
//! Deliberately returns a *name*, never a glyph: `source/IconGlyphs.mc`
//! (generated per project from the icon catalogue) is the one place a
//! catalogue name becomes an actual drawn character, for every icon -- a
//! weather condition or otherwise -- not just this one. See ts/src/icons.ts
//! for the fuller reasoning.
//!
//! Day names only for now -- there is no sunrise/sunset source yet to know
//! whether the `_night` variant applies on-device (see docs/limitations.md).
module WfbWeather {

    //! `condition` null or out of the documented 0-53 range both resolve to
    //! "weather_unknown", matching ts/src/icons.ts for a null condition.
    function chooseIcon(condition as Number?) as String {
        if (condition == null) {
            return "weather_unknown";
        }
        switch (condition) {
            case 0: return "weather_sunny";  // CONDITION_CLEAR
            case 1: return "weather_cloudy_light";  // CONDITION_PARTLY_CLOUDY
            case 2: return "weather_cloudy_heavy";  // CONDITION_MOSTLY_CLOUDY
            case 3: return "weather_rain";  // CONDITION_RAIN
            case 4: return "weather_snow";  // CONDITION_SNOW
            case 5: return "weather_windy";  // CONDITION_WINDY
            case 6: return "weather_thunderstorm";  // CONDITION_THUNDERSTORMS
            case 7: return "weather_wintry_mix";  // CONDITION_WINTRY_MIX
            case 8: return "weather_fog";  // CONDITION_FOG
            case 9: return "weather_haze";  // CONDITION_HAZY
            case 10: return "weather_hail";  // CONDITION_HAIL
            case 11: return "weather_rain_heavy";  // CONDITION_SCATTERED_SHOWERS
            case 12: return "weather_thunderstorm_showers";  // CONDITION_SCATTERED_THUNDERSTORMS
            case 13: return "weather_rain";  // CONDITION_UNKNOWN_PRECIPITATION -- no dedicated glyph; rain reads closest
            case 14: return "weather_rain_light";  // CONDITION_LIGHT_RAIN
            case 15: return "weather_rain_heavy";  // CONDITION_HEAVY_RAIN
            case 16: return "weather_snow";  // CONDITION_LIGHT_SNOW
            case 17: return "weather_snow_heavy";  // CONDITION_HEAVY_SNOW
            case 18: return "weather_wintry_mix";  // CONDITION_LIGHT_RAIN_SNOW
            case 19: return "weather_wintry_mix";  // CONDITION_HEAVY_RAIN_SNOW
            case 20: return "weather_cloudy";  // CONDITION_CLOUDY
            case 21: return "weather_wintry_mix";  // CONDITION_RAIN_SNOW
            case 22: return "weather_sunny_overcast";  // CONDITION_PARTLY_CLEAR
            case 23: return "weather_sunny_overcast";  // CONDITION_MOSTLY_CLEAR
            case 24: return "weather_rain_light";  // CONDITION_LIGHT_SHOWERS
            case 25: return "weather_rain_heavy";  // CONDITION_SHOWERS
            case 26: return "weather_rain_heavy";  // CONDITION_HEAVY_SHOWERS
            case 27: return "weather_rain_light";  // CONDITION_CHANCE_OF_SHOWERS
            case 28: return "weather_lightning";  // CONDITION_CHANCE_OF_THUNDERSTORMS
            case 29: return "weather_fog";  // CONDITION_MIST
            case 30: return "weather_dust";  // CONDITION_DUST
            case 31: return "weather_rain_light";  // CONDITION_DRIZZLE
            case 32: return "weather_tornado";  // CONDITION_TORNADO
            case 33: return "weather_smoke";  // CONDITION_SMOKE
            case 34: return "weather_ice";  // CONDITION_ICE
            case 35: return "weather_sandstorm";  // CONDITION_SAND
            case 36: return "weather_strong_wind";  // CONDITION_SQUALL
            case 37: return "weather_sandstorm";  // CONDITION_SANDSTORM
            case 38: return "weather_volcano";  // CONDITION_VOLCANIC_ASH
            case 39: return "weather_haze";  // CONDITION_HAZE
            case 40: return "weather_sunny_overcast";  // CONDITION_FAIR
            case 41: return "weather_hurricane";  // CONDITION_HURRICANE
            case 42: return "weather_hurricane_warning";  // CONDITION_TROPICAL_STORM
            case 43: return "weather_snow";  // CONDITION_CHANCE_OF_SNOW
            case 44: return "weather_wintry_mix";  // CONDITION_CHANCE_OF_RAIN_SNOW
            case 45: return "weather_rain";  // CONDITION_CLOUDY_CHANCE_OF_RAIN
            case 46: return "weather_snow";  // CONDITION_CLOUDY_CHANCE_OF_SNOW
            case 47: return "weather_wintry_mix";  // CONDITION_CLOUDY_CHANCE_OF_RAIN_SNOW
            case 48: return "weather_snow";  // CONDITION_FLURRIES
            case 49: return "weather_sleet";  // CONDITION_FREEZING_RAIN
            case 50: return "weather_sleet";  // CONDITION_SLEET
            case 51: return "weather_snow";  // CONDITION_ICE_SNOW
            case 52: return "weather_cloudy_light";  // CONDITION_THIN_CLOUDS -- lighter than CLOUDY(20)
            case 53: return "weather_unknown";  // CONDITION_UNKNOWN
            default: return "weather_unknown";
        }
    }
}
